CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', url TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, screenshot TEXT NOT NULL DEFAULT '', device TEXT NOT NULL DEFAULT 'phone', canva TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, caption TEXT NOT NULL, image TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft', remote_id TEXT, error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, published_at TEXT);
